import { describe, expect, it } from "vitest"
import { canWorkOn, followUpCounts, followUpStatus, followUpWhen, sortFollowUps } from "./follow-ups"
import { buildInbox } from "./inbox"
import { FollowUpStatus, type ClientFollowUp } from "../../types/work-crm"

const TODAY = "2026-10-20"
const fu = (id: string, dueDate: string, over: Partial<ClientFollowUp> = {}): ClientFollowUp => ({ id, workspaceId: "ws", clientId: "c", title: id, dueDate, ownerId: "emma", createdAt: "", updatedAt: "", ...over })

describe("client follow-ups (CRM step 5)", () => {
  it("puts each follow-up in the right bucket", () => {
    expect(followUpWhen(fu("a", "2026-10-19"), TODAY)).toBe("late")
    expect(followUpWhen(fu("b", TODAY), TODAY)).toBe("today")
    expect(followUpWhen(fu("c", "2026-10-27"), TODAY)).toBe("week")
    expect(followUpWhen(fu("d", "2026-10-28"), TODAY)).toBe("later")
    expect(followUpWhen(fu("e", "2026-10-01", { doneAt: "2026-10-02T09:00:00Z" }), TODAY)).toBe("done")
    expect(followUpStatus(fu("f", TODAY))).toBe(FollowUpStatus.TODO)
    expect(followUpStatus(fu("g", TODAY, { status: FollowUpStatus.IN_PROGRESS }))).toBe(FollowUpStatus.IN_PROGRESS)
  })

  it("lists open ones by date first, then the done ones latest first", () => {
    const list = [
      fu("done-old", "2026-10-01", { doneAt: "2026-10-01T09:00:00Z" }),
      fu("later", "2026-11-30"),
      fu("done-new", "2026-10-10", { doneAt: "2026-10-12T09:00:00Z" }),
      fu("late", "2026-10-15"),
    ]
    expect(sortFollowUps(list).map((f) => f.id)).toEqual(["late", "later", "done-new", "done-old"])
  })

  it("counts late, today, the coming week and what was done in the last 30 days", () => {
    const list = [fu("a", "2026-10-19"), fu("b", TODAY), fu("c", "2026-10-22"), fu("d", "2026-12-01"), fu("e", "2026-10-01", { doneAt: "2026-10-05T09:00:00Z" }), fu("f", "2026-08-01", { doneAt: "2026-08-02T09:00:00Z" })]
    expect(followUpCounts(list, TODAY)).toEqual({ open: 4, late: 1, today: 1, week: 1, doneRecently: 1 })
  })

  it("lets client editors and the owner work on a follow-up", () => {
    const f = fu("a", TODAY)
    expect(canWorkOn(f, "emma", false)).toBe(true)
    expect(canWorkOn(f, "sara", false)).toBe(false)
    expect(canWorkOn(f, undefined, true)).toBe(true)
  })

  it("rings the bell for the owner's follow-ups due today or late", () => {
    const base = { rights: { approveTime: false, invoices: false, hr: false }, employees: [], reviews: [], entries: [], leave: [], expenses: [], invoices: [], documents: [], tasks: [], today: TODAY }
    const followUps = [fu("late", "2026-10-18"), fu("today", TODAY), fu("soon", "2026-10-22"), fu("done", "2026-10-18", { doneAt: "2026-10-18T10:00:00Z" }), fu("other", TODAY, { ownerId: "sara" })]
    const mine = buildInbox({ ...base, viewer: { employeeId: "emma", isAdmin: false }, followUps })
    expect(mine).toEqual([expect.objectContaining({ title: "inboxFollowUps", message: "inboxFollowUpsLate", values: { count: 2, late: 1 }, href: "/dashboard/my-work" })])
    const todayOnly = buildInbox({ ...base, viewer: { employeeId: "sara", isAdmin: false }, followUps })
    expect(todayOnly[0]).toMatchObject({ message: "inboxFollowUpsToday", values: { count: 1, late: 0 } })
    expect(buildInbox({ ...base, viewer: { employeeId: "karim", isAdmin: false }, followUps })).toEqual([])
  })
})
